 * PostToolUse hook (Bash): audit log for all shell commands.
 * Appends JSONL entries to session-state/bash-audit.jsonl.
 * Logging only — always exits 0.
 * Rotates file at 5 MB.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..', '..', '..');
const AUDIT_FILE = path.join(REPO_ROOT, 'operations', 'engineering', 'records', 'session-state', 'bash-audit.jsonl');
const MAX_BYTES = 5 * 1024 * 1024; // 5 MB
const MAX_STDIN = 512 * 1024;

function rotateIfNeeded() {
  try {
    if (fs.existsSync(AUDIT_FILE) && fs.statSync(AUDIT_FILE).size > MAX_BYTES) {
      const archiveDir = path.join(path.dirname(AUDIT_FILE), 'archive');
      fs.mkdirSync(archiveDir, { recursive: true });
      const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
      fs.renameSync(AUDIT_FILE, path.join(archiveDir, `bash-audit-${ts}.jsonl`));
    }
  } catch (e) {
    process.stderr.write(`[bash-audit] rotate error: ${e.message}\n`);
  }
}

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
  if (raw.length < MAX_STDIN) raw += chunk.substring(0, MAX_STDIN - raw.length);
});
process.stdin.on('end', () => {
  try {
    const input = raw.trim() ? JSON.parse(raw) : {};
    const toolName = input.tool_name || input.tool || '';

    if (toolName !== 'Bash') {
      process.exit(0);
      return;
    }

    const toolInput = input.tool_input || input.input || {};
    const command = typeof toolInput === 'object' ? (toolInput.command || '') : String(toolInput);
    const sessionId = input.session_id || process.env.CLAUDE_SESSION_ID || 'unknown';

    // Extract exit code from tool output if available
    const toolOutput = input.tool_output || input.output || '';
    const outputStr = typeof toolOutput === 'object' ? JSON.stringify(toolOutput) : String(toolOutput);
    let exitCode = 0;
    const exitMatch = outputStr.match(/exit code:\s*(\d+)/i);
    if (exitMatch) {
      exitCode = parseInt(exitMatch[1], 10);
    } else if (input.exit_code !== undefined) {
      exitCode = input.exit_code;
    }

    const entry = {
      timestamp: new Date().toISOString(),
      command: command.slice(0, 2000),
      exit_code: exitCode,
      session_id: sessionId
    };

    rotateIfNeeded();
    fs.mkdirSync(path.dirname(AUDIT_FILE), { recursive: true });
    fs.appendFileSync(AUDIT_FILE, JSON.stringify(entry) + '\n', 'utf8');

  } catch (e) {
    process.stderr.write(`[bash-audit] ${e.message}\n`);
  }

  process.exit(0);
});
"}

