/// Record a session completion/failure event in the operations graph.
/// This closes the execution→tracking loop: the daemon observes session
/// endings and writes structured events that tracking tools can query.
fn record_session_event(session: &Session, state: &SessionState, graph_path: &std::path::Path) {
    let action = match state {
        SessionState::Completed => "task-completed",
        SessionState::Failed => "task-failed",
        _ => return,
    };

    let now = chrono::Utc::now().to_rfc3339();
    let seed = format!("event-{action}-session-{}-{now}", session.id);

    let mut attrs = HashMap::new();
    attrs.insert("type".to_string(), "event".to_string());
    attrs.insert("action".to_string(), action.to_string());
    attrs.insert("subject".to_string(), format!("session-{}", session.id));
    attrs.insert("actor".to_string(), "daemon".to_string());
    attrs.insert("timestamp".to_string(), now);
    attrs.insert("session-id".to_string(), session.id.clone());

    // Truncate task for the reason field
    let task_preview = if session.task.len() > 100 {
        format!("{}...", &session.task[..97])
    } else {
        session.task.clone()
    };
    attrs.insert("reason".to_string(), task_preview);

    match Graph::open(graph_path) {
        Ok(mut graph) => {
            graph.insert_entity(&seed, attrs);
            if let Err(e) = graph.save() {
                tracing::error!("Failed to save event to ops graph: {e}");
            }
        }
        Err(e) => {
            tracing::error!("Failed to open ops graph for event recording: {e}");
        }
    }
}","replace_all":false}

