fn write_failure_report(session: &Session, session_dir: &std::path::Path) {
    let log_path = session_dir.join(format!("{}.log", session.id));
    let report_path = session_dir.join(format!("{}.failure", session.id));

    let log_content = std::fs::read_to_string(&log_path).unwrap_or_default();
    let log_preview = if log_content.len() > 2000 {
        format!("{}...\n[truncated at 2000 chars]", &log_content[..2000])
    } else if log_content.is_empty() {
        "(no output)".to_string()
    } else {
        log_content
    };

    let report = format!(
        "---\nid: failure-{id}\ntype: failure-report\nsession-id: {id}\ndate: {date}\ntask-preview: {task}\n---\n\n# Session {id} Failed\n\n## Task\n{full_task}\n\n## Log Output\n```\n{log}\n```\n\n## Questions for Review\n- Was the right office dispatched for this work type?\n- Was the prompt sufficient for the task?\n- What knowledge was missing that would have prevented failure?\n- Should a duty or skill be updated?\n",
        id = session.id,
        date = chrono::Utc::now().to_rfc3339(),
        task = if session.task.len() > 80 { &session.task[..80] } else { &session.task },
        full_task = session.task,
        log = log_preview,
    );

    if let Err(e) = std::fs::write(&report_path, report) {
        tracing::error!("Failed to write failure report for {}: {e}", session.id);
    } else {
        tracing::info!("Wrote failure report for session {}", session.id);
    }
}

