/**
 * Extract text output and metrics from claude --output-format json.
 *
 * Usage: node extract-session-output.js <json-path> <log-path> <metrics-path>
 *
 * Reads the JSON output from `claude -p --output-format json`, writes:
 * - <log-path>: the text result (human-readable)
 * - <metrics-path>: JSON with tokens_in, tokens_out, cost, tool_calls, duration_ms
 *
 * On any error, copies the raw JSON to <log-path> so the log is never empty.
 */
'use strict';

const fs = require('fs');

const [,, jsonPath, logPath, metricsPath] = process.argv;

if (!jsonPath || !logPath || !metricsPath) {
  process.exit(0);
}

try {
  const raw = fs.readFileSync(jsonPath, 'utf8');
  const r = JSON.parse(raw);

  // Extract text result
  const text = typeof r.result === 'string'
    ? r.result
    : JSON.stringify(r.result);
  fs.writeFileSync(logPath, text);

  // Extract metrics
  const u = r.usage || {};
  const metrics = {
    tokens_in: (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0),
    tokens_out: u.output_tokens || 0,
    cost: r.total_cost_usd || 0,
    tool_calls: r.num_turns || 0,
    duration_ms: r.duration_ms || 0,
  };
  fs.writeFileSync(metricsPath, JSON.stringify(metrics));
} catch (e) {
  // On failure, copy raw JSON to log so it's not empty
  try {
    fs.copyFileSync(jsonPath, logPath);
  } catch (_) {
    // nothing to do
  }
}
